1	/**
2	 * Minimal DOM mock for testing frontend components in Node.js.
3	 * Provides just enough of the DOM API to exercise component logic.
4	 */
5	
6	class MockElement {
7	  constructor(tag) {
8	    this.tagName = tag.toUpperCase();
9	    this.className = '';
10	    this.innerHTML = '';
11	    this.textContent = '';
12	    this.children = [];
13	    this.attributes = {};
14	    this.dataset = {};
15	    this._eventListeners = {};
16	    this._classList = new Set();
17	    this.parentNode = null;
18	    this.style = {};
19	  }
20	
21	  get classList() {
22	    const self = this;
23	    return {
24	      add(cls) { self._classList.add(cls); },
25	      remove(cls) { self._classList.delete(cls); },
26	      contains(cls) { return self._classList.has(cls); },
27	      toggle(cls) {
28	        if (self._classList.has(cls)) { self._classList.delete(cls); return false; }
29	        self._classList.add(cls); return true;
30	      }
31	    };
32	  }
33	
34	  setAttribute(name, value) {
35	    this.attributes[name] = value;
36	    if (name.startsWith('data-')) {
37	      this.dataset[name.slice(5).replace(/-([a-z])/g, (_, c) => c.toUpperCase())] = value;
38	    }
39	  }
40	
41	  getAttribute(name) {
42	    return this.attributes[name] ?? null;
43	  }
44	
45	  addEventListener(event, handler) {
46	    if (!this._eventListeners[event]) this._eventListeners[event] = [];
47	    this._eventListeners[event].push(handler);
48	  }
49	
50	  removeEventListener(event, handler) {
51	    if (this._eventListeners[event]) {
52	      this._eventListeners[event] = this._eventListeners[event].filter(h => h !== handler);
53	    }
54	  }
55	
56	  dispatchEvent(event) {
57	    const handlers = this._eventListeners[event.type] || [];
58	    for (const h of handlers) h(event);
59	  }
60	
61	  click() {
62	    this.dispatchEvent({ type: 'click', target: this });
63	  }
64	
65	  appendChild(child) {
66	    child.parentNode = this;
67	    this.children.push(child);
68	    return child;
69	  }
70	
71	  remove() {
72	    if (this.parentNode) {
73	      this.parentNode.children = this.parentNode.children.filter(c => c !== this);
74	      this.parentNode = null;
75	    }
76	  }
77	
78	  querySelector(selector) {
79	    // First check real children (appended MockElements)
80	    const fromChildren = this._queryChildren(selector)[0];
81	    if (fromChildren) return fromChildren;
82	
83	    // Fall back to searching innerHTML string and returning a stub element
84	    return this._queryInnerHTML(selector);
85	  }
86	
87	  querySelectorAll(selector) {
88	    const fromChildren = this._queryChildren(selector);
89	    if (fromChildren.length > 0) return fromChildren;
90	
91	    // For innerHTML-based matches, collect all matching stubs
92	    return this._queryAllInnerHTML(selector);
93	  }
94	
95	  _queryChildren(selector) {
96	    const results = [];
97	    const match = (el) => {
98	      if (this._matchesSelector(el, selector)) results.push(el);
99	      for (const child of el.children) match(child);
100	    };
101	    for (const child of this.children) match(child);
102	    return results;
103	  }
104	
105	  _matchesSelector(el, selector) {
106	    if (selector.startsWith('.')) {
107	      const cls = selector.slice(1);
108	      return el.className.includes(cls) || el._classList.has(cls);
109	    } else if (selector.startsWith('#')) {
110	      return el.attributes.id === selector.slice(1);
111	    } else if (selector.startsWith('[')) {
112	      const m = selector.match(/\[([^\]=]+)(?:="([^"]*)")?\]/);
113	      if (m && el.attributes[m[1]] !== undefined) {
114	        return !m[2] || el.attributes[m[1]] === m[2];
115	      }
116	      return false;
117	    } else {
118	      return el.tagName === selector.toUpperCase();
119	    }
120	  }
121	
122	  _queryInnerHTML(selector) {
123	    const html = this.innerHTML;
124	    if (!html) return null;
125	
126	    if (selector.startsWith('.')) {
127	      const cls = selector.slice(1);
128	      // Match class="...cls..." or class='...cls...'
129	      const regex = new RegExp(`class="[^"]*\\b${cls}\\b[^"]*"`, 'i');
130	      if (regex.test(html)) return this._stubFromHTML(html, selector);
131	    } else if (selector.startsWith('#')) {
132	      const id = selector.slice(1);
133	      if (html.includes(`id="${id}"`)) return this._stubFromHTML(html, selector);
134	    } else if (selector.startsWith('[')) {
135	      const m = selector.match(/\[([^\]=]+)(?:="([^"]*)")?\]/);
136	      if (m) {
137	        const attrPattern = m[2] ? `${m[1]}="${m[2]}"` : m[1];
138	        if (html.includes(attrPattern)) return this._stubFromHTML(html, selector);
139	      }
140	    }
141	    return null;
142	  }
143	
144	  _queryAllInnerHTML(selector) {
145	    const html = this.innerHTML;
146	    if (!html) return [];
147	
148	    const results = [];
149	    if (selector.startsWith('.')) {
150	      const cls = selector.slice(1);
151	      const regex = new RegExp(`class="[^"]*\\b${cls}\\b[^"]*"`, 'gi');
152	      const matches = html.match(regex) || [];
153	      for (const m of matches) results.push(this._stubFromHTML(html, selector));
154	    } else if (selector.startsWith('[')) {
155	      const m = selector.match(/\[([^\]=]+)(?:="([^"]*)")?\]/);
156	      if (m) {
157	        const attr = m[1];
158	        const regex = new RegExp(`${attr}="([^"]*)"`, 'gi');
159	        const matches = html.match(regex) || [];
160	        for (const match of matches) {
161	          const val = match.split('="')[1]?.slice(0, -1);
162	          const stub = new MockElement('div');
163	          stub.dataset[attr.replace('data-', '').replace(/-([a-z])/g, (_, c) => c.toUpperCase())] = val;
164	          stub.attributes[attr] = val;
165	          results.push(stub);
166	        }
167	      }
168	    }
169	    return results;
170	  }
171	
172	  _stubFromHTML(html, selector) {
173	    // Return a stub MockElement that supports addEventListener etc.
174	    const stub = new MockElement('div');
175	    if (selector.startsWith('.')) stub.className = selector.slice(1);
176	    return stub;
177	  }
178	}
179	
180	class MockDocument {
181	  constructor() {
182	    this.body = new MockElement('body');
183	  }
184	
185	  createElement(tag) {
186	    return new MockElement(tag);
187	  }
188	
189	  getElementById(id) {
190	    // Search appended children first
191	    const search = (el) => {
192	      if (el.attributes.id === id) return el;
193	      for (const child of el.children) {
194	        const found = search(child);
195	        if (found) return found;
196	      }
197	      return null;
198	    };
199	    const found = search(this.body);
200	    if (found) return found;
201	
202	    // Fall back to innerHTML search across all children
203	    for (const child of this.body.children) {
204	      if (child.innerHTML && child.innerHTML.includes(`id="${id}"`)) {
205	        const stub = new MockElement('button');
206	        stub.attributes.id = id;
207	        return stub;
208	      }
209	    }
210	    return null;
211	  }
212	}
213	
