39	    const record = {
40	      ...device,
41	      status: 'online',
42	      lastSeen: Date.now(),
43	      secret: undefined // never expose device secrets
44	    };
45	    const id = await DB.add('devices', record);
46	    record.id = id;
47	    this._devices.push(record);
48	    this._emit('device:registered', record);
49	    return record;
50	  },
