60	  async sendUnlockCommand(deviceId, reason, actor) {
61	    if (!reason || reason.length < 10) {
62	      return { success: false, error: 'Reason must be at least 10 characters' };
63	    }
64	
65	    const device = this._devices.find(d => d.id === deviceId);
66	    if (!device) return { success: false, error: `Device ${deviceId} not found` };
67	
68	    const command = {
69	      deviceId,
70	      type: 'unlock',
71	      reason,
72	      actor,
73	      status: 'pending',
74	      createdAt: Date.now(),
75	      ackAt: null,
76	      retryCount: 0,
77	      lastRetry: null
78	    };
79	
80	    const cmdId = await DB.add('command_outbox', command);
81	    command.id = cmdId;
82	
83	    await addAuditLog('unlock_command', actor, {
84	      deviceId,
85	      deviceName: device.name,
86	      reason,
87	      commandId: cmdId
