1	import DB from '../database.js';
2	import Store from '../store.js';
3	import { requireRole, getCurrentUser, hasRole } from '../services/auth-service.js';
4	import { createEntryPermission, getPermissionsForReservation, getPermissionStatusLabel } from '../services/permissions.js';
5	import { scheduleReservationReminders, createNotification } from '../services/notifications.js';
6	import { addAuditLog } from '../services/audit.js';
7	import { checkRateLimit } from '../services/rate-limits.js';
8	import { showModal, closeModal } from '../components/modal.js';
9	import { renderPaginatedTable } from '../components/table.js';
10	import { showNotification } from '../components/notifications.js';
11	
12	export async function renderReservations(container) {
13	  if (!await requireRole(['visitor', 'operator', 'admin'])) return;
14	  const user = getCurrentUser();
15	  const canManage = hasRole(['admin', 'operator']);
16	
17	  // Service-layer isolation: load only the actor's own records for non-privileged roles
18	  let reservations;
19	  if (canManage) {
20	    reservations = await DB.getAll('reservations');
21	  } else {
22	    reservations = await DB.getByIndex('reservations', 'userId', user.id);
23	  }
24	
25	  container.innerHTML = `
26	    <div class="view-header">
27	      <h1>Reservations</h1>
28	      <button class="btn btn-primary" id="add-reservation-btn">+ New Reservation</button>
29	    </div>
30	    <div class="filters">
31	      <input type="text" id="reservation-search" placeholder="Search..." class="input" />
32	      <select id="reservation-status-filter" class="input">
33	        <option value="">All Statuses</option>
34	        <option value="pending">Pending</option>
35	        <option value="approved">Approved</option>
36	        <option value="denied">Denied</option>
37	        <option value="completed">Completed</option>
38	      </select>
39	    </div>
40	    <div id="reservations-table"></div>
41	  `;
42	
43	  const columns = [
44	    { key: 'visitorName', label: 'Visitor', sortable: true },
45	    { key: 'date', label: 'Date', sortable: true },
46	    { key: 'time', label: 'Time', sortable: true },
47	    { key: 'zone', label: 'Zone', sortable: true },
48	    { key: 'entryPolicy', label: 'Entry Policy' },
49	    { key: 'status', label: 'Status', sortable: true, render: (val) => `<span class="badge badge-${val}">${val}</span>` },
50	    { key: 'permissionStatus', label: 'Permission' },
51	    { key: 'actions', label: 'Actions', render: (_, row) => {
52	      let btns = `<button class="btn btn-sm" data-action="view-perm" data-id="${row.id}">Permissions</button>`;
53	      if (canManage && row.status === 'pending') {
54	        btns += ` <button class="btn btn-sm btn-primary" data-action="approve" data-id="${row.id}">Approve</button>`;
55	        btns += ` <button class="btn btn-sm btn-danger" data-action="deny" data-id="${row.id}">Deny</button>`;
56	      }
57	      btns += ` <button class="btn btn-sm btn-danger" data-action="delete" data-id="${row.id}">Delete</button>`;
58	      return btns;
59	    }}
60	  ];
61	
62	  // Attach permission status
63	  for (const r of reservations) {
64	    const perms = await getPermissionsForReservation(r.id, user);
65	    r.permissionStatus = perms.length > 0
66	      ? perms.map(p => `<span class="badge badge-${p.status}">${getPermissionStatusLabel(p)}</span>`).join(' ')
67	      : '<span class="badge badge-pending">None</span>';
68	    r.entryPolicy = r.entryPolicy || 'single-use';
69	  }
70	
71	  const tableId = 'reservations';
72	  Store.initTable(tableId, reservations, { pageSize: 10, sortKey: 'date', sortDir: 'desc' });
73	
74	  function refresh() {
75	    renderPaginatedTable(document.getElementById('reservations-table'), tableId, columns, bindActions);
76	  }
77	
78	  refresh();
79	
80	  document.getElementById('reservation-search').addEventListener('input', (e) => {
81	    const q = e.target.value.toLowerCase();
82	    Store.setTableFilter(tableId, q ? (r => r.visitorName.toLowerCase().includes(q) || r.zone.toLowerCase().includes(q)) : null);
83	    refresh();
84	  });
85	
86	  document.getElementById('reservation-status-filter').addEventListener('change', (e) => {
87	    const s = e.target.value;
88	    Store.setTableFilter(tableId, s ? (r => r.status === s) : null);
89	    refresh();
90	  });
91	
92	  document.getElementById('add-reservation-btn').addEventListener('click', () => openReservationForm());
93	
94	  function bindActions() {
95	    document.querySelectorAll('[data-action="approve"]').forEach(btn => {
96	      btn.addEventListener('click', async () => {
97	        // Service-level: only admin/operator may approve
98	        if (!canManage) { showNotification('Not authorized to approve reservations', 'error'); return; }
99	        const r = await DB.get('reservations', Number(btn.dataset.id));
100	        if (!r) return;
101	        const before = { ...r };
102	        r.status = 'approved';
103	        await DB.put('reservations', r);
104	        // Only create permission if none exists yet for this reservation
105	        const existingPerms = await getPermissionsForReservation(r.id, user);
106	        if (existingPerms.length === 0) {
107	          await createEntryPermission(r, r.entryPolicy || 'single-use');
108	        }
109	        await scheduleReservationReminders(r);
110	        await createNotification({
111	          userId: r.userId,
112	          templateId: 'reservation_approved',
113	          variables: { reservationId: r.id },
114	          type: 'success'
115	        });
116	        await addAuditLog('reservation_approved', user.username, { reservationId: r.id }, before, r);
117	        showNotification('Reservation approved', 'success');
118	        renderReservations(container);
119	      });
120	    });
121	
122	    document.querySelectorAll('[data-action="deny"]').forEach(btn => {
123	      btn.addEventListener('click', async () => {
124	        // Service-level: only admin/operator may deny
125	        if (!canManage) { showNotification('Not authorized to deny reservations', 'error'); return; }
126	        const r = await DB.get('reservations', Number(btn.dataset.id));
127	        if (!r) return;
128	        const before = { ...r };
129	        r.status = 'denied';
130	        await DB.put('reservations', r);
131	        await createNotification({
132	          userId: r.userId,
133	          templateId: 'reservation_denied',
134	          variables: { reservationId: r.id },
135	          type: 'warning'
136	        });
137	        await addAuditLog('reservation_denied', user.username, { reservationId: r.id }, before, r);
138	        showNotification('Reservation denied', 'warning');
139	        renderReservations(container);
140	      });
141	    });
142	
143	    document.querySelectorAll('[data-action="delete"]').forEach(btn => {
144	      btn.addEventListener('click', async () => {
145	        const reservation = await DB.get('reservations', Number(btn.dataset.id));
146	        if (!reservation) return;
147	
148	        // Object-level authorization: only the owner or privileged roles may delete
149	        if (reservation.userId !== user.id && !canManage) {
150	          showNotification('Not authorized to delete this reservation', 'error');
151	          return;
152	        }
153	
154	        await DB.remove('reservations', reservation.id);
155	        await addAuditLog('reservation_deleted', user.username, { reservationId: reservation.id });
156	        showNotification('Reservation deleted', 'success');
157	        renderReservations(container);
158	      });
159	    });
160	
161	    document.querySelectorAll('[data-action="view-perm"]').forEach(btn => {
162	      btn.addEventListener('click', async () => {
163	        const perms = await getPermissionsForReservation(Number(btn.dataset.id), user);
164	        showModal('Entry Permissions', perms.length === 0
165	          ? '<p>No permissions generated yet. Reservation must be approved first.</p><div class="form-actions"><button class="btn btn-secondary" id="close-perm-modal">Close</button></div>'
