267	          <select name="locale" class="input">
268	            <option value="en" ${(!existing || existing.locale === 'en') ? 'selected' : ''}>English</option>
269	            <option value="es" ${existing?.locale === 'es' ? 'selected' : ''}>Spanish</option>
270	            <option value="fr" ${existing?.locale === 'fr' ? 'selected' : ''}>French</option>
271	            <option value="de" ${existing?.locale === 'de' ? 'selected' : ''}>German</option>
272	            <option value="zh" ${existing?.locale === 'zh' ? 'selected' : ''}>Chinese</option>
273	          </select>
274	        </label>
275	        <label class="form-label">Source
276	          <input type="text" name="source" class="input" value="${escapeHTML(existing?.source || '')}" placeholder="e.g., manual, import" />
277	        </label>
278	        <fieldset class="variant-fieldset">
279	          <legend>Multilingual Variant (optional)</legend>
280	          <label class="form-label">Variant Locale
281	            <select name="variantLocale" class="input">
282	              <option value="">None</option>
283	              <option value="es">Spanish</option>
284	              <option value="fr">French</option>
285	              <option value="de">German</option>
286	              <option value="zh">Chinese</option>
287	            </select>
288	          </label>
289	          <label class="form-label">Variant Title
290	            <input type="text" name="variantTitle" class="input" />
291	          </label>
292	          <label class="form-label">Variant Body
293	            <textarea name="variantBody" class="input" rows="3"></textarea>
294	          </label>
295	        </fieldset>
296	        <div class="form-actions">
297	          <button type="submit" class="btn btn-primary">${existing ? 'Update' : 'Create'}</button>
298	          <button type="button" class="btn btn-secondary" id="cancel-content">Cancel</button>
299	        </div>
300	      </form>
301	    `);
302	
303	    document.getElementById('cancel-content').addEventListener('click', closeModal);
