307	      const data = Object.fromEntries(fd);
308	
309	      // Build variants
310	      const variants = existing?.variants || {};
311	      if (data.variantLocale && data.variantTitle) {
312	        variants[data.variantLocale] = { title: data.variantTitle, body: data.variantBody || '' };
313	      }
314	
315	      // Scan for compliance
316	      const violations = scanContent(data.body);
317	
318	      if (existing) {
319	        await updateContent(existing.id, {
320	          title: data.title,
321	          body: data.body,
322	          locale: data.locale,
323	          variants
324	        }, user.username);
325	        // Update compliance
326	        existing.violations = violations;
327	        existing.violationCount = violations.length;
328	        existing.flagged = violations.length > 0;
329	        existing.scannedAt = Date.now();
330	        await DB.put('content', existing);
331	      } else {
332	        const record = await createContent({
333	          title: data.title,
334	          body: data.body,
335	          source: data.source,
336	          locale: data.locale,
337	          variants,
338	          author: user.username,
339	          authorId: user.id
340	        });
341	        record.violations = violations;
342	        record.violationCount = violations.length;
343	        record.flagged = violations.length > 0;
344	        record.scannedAt = Date.now();
345	        await DB.put('content', record);
346	
347	        if (record.flagged) {
348	          await createNotification({
349	            userId: user.id,
350	            templateId: 'content_flagged',
351	            variables: { contentTitle: data.title },
352	            type: 'warning'
353	          });
354	        }
355	      }
356	
357	      showNotification(violations.length > 0 ? 'Content saved (flagged!)' : 'Content saved', violations.length > 0 ? 'warning' : 'success');
358	      closeModal();
359	      renderContent(container);
360	    });
361	  }
362	}
