1	/**
2	 * IndexedDB wrapper for HarborGate data.
3	 * Supports encryption at rest for sensitive stores via a session-derived CryptoKey.
4	 */
5	const DB_NAME = 'harborgate';
6	const DB_VERSION = 2;
7	
8	// Stores whose records are encrypted at rest when a session key is available.
9	// NOTE: 'roles' is excluded — role definitions contain no sensitive data and
10	// must be readable pre-auth. 'users' IS included: only index and lockout fields
11	// (username, role, failedAttempts, lockedUntil, banned) are preserved as
12	// plaintext. Sensitive credentials (passwordHash, passwordSalt) are encrypted
13	// in the payload — the login flow derives the KEK and unwraps the DEK before
14	// needing them.
15	const ENCRYPTED_STORES = new Set([
16	  'users',
17	  'reservations',
18	  'entry_permissions',
19	  'devices',
20	  'pois',
21	  'content',
22	  'reports',
23	  'audit_logs',
24	  'notifications',
25	  'command_outbox',
26	  'rate_limits',
27	  'zones',
28	  'geofences'
29	]);
30	
31	const STORES = {
32	  users: { keyPath: 'id', autoIncrement: true, indexes: [{ name: 'username', keyPath: 'username', unique: true }, { name: 'role', keyPath: 'role' }] },
33	  roles: { keyPath: 'id', autoIncrement: true, indexes: [{ name: 'name', keyPath: 'name', unique: true }] },
34	  rate_limits: { keyPath: 'id', autoIncrement: true, indexes: [{ name: 'scope', keyPath: 'scope' }, { name: 'action', keyPath: 'action' }] },
35	  reservations: { keyPath: 'id', autoIncrement: true, indexes: [{ name: 'userId', keyPath: 'userId' }, { name: 'status', keyPath: 'status' }] },
36	  entry_permissions: { keyPath: 'id', autoIncrement: true, indexes: [{ name: 'reservationId', keyPath: 'reservationId' }, { name: 'status', keyPath: 'status' }] },
37	  devices: { keyPath: 'id', autoIncrement: true, indexes: [{ name: 'zone', keyPath: 'zone' }, { name: 'status', keyPath: 'status' }] },
