    poi.name = 'New';
    const updated = await mapSvc.updatePOI(poi);
    assert.equal(updated.name, 'New');
    const stored = await DB.get('pois', poi.id);
    assert.equal(stored.name, 'New');
  });
});

describe('map/deletePOI', () => {
  it('removes a POI from the database', async () => {
