1	/**
2	 * Authentication & Session service.
3	 * - Password policy: min 12 chars, 1 upper, 1 lower, 1 number, 1 symbol
4	 * - 5 failed attempts → 15 min lockout
5	 * - 30-min idle timeout, "Extend Session" prompt at 25 min
6	 * - Session token in localStorage
7	 * - Default admin account seeded on first run
8	 */
9	import DB from '../database.js';
10	import Crypto from '../crypto.js';
11	import Store from '../store.js';
12	import { addAuditLog } from './audit.js';
13	import { checkRateLimit } from './rate-limits.js';
14	import {
15	  validatePassword as _validatePassword,
16	  isAccountLocked as _isAccountLocked,
17	  processFailedLogin,
18	  processSuccessfulLogin,
19	  isSessionExpired,
20	  MAX_ATTEMPTS,
21	  LOCKOUT_DURATION,
22	  SESSION_TIMEOUT,
23	  SESSION_WARNING,
24	  ROLE_DEFINITIONS,
25	  hasPermissionForRole
26	} from '../lib/auth-logic.js';
27	import { setEncryptionKey, clearEncryptionKey, getEncryptionKey } from '../database.js';
28	
29	const SESSION_KEY = 'hg_session';
30	const WRAPPED_KEYS_KEY = 'hg_wrapped_keys';
31	
32	function getWrappedKeys() {
33	  try { return JSON.parse(localStorage.getItem(WRAPPED_KEYS_KEY) || '{}'); } catch { return {}; }
34	}
35	
36	function setWrappedKeys(keys) {
37	  localStorage.setItem(WRAPPED_KEYS_KEY, JSON.stringify(keys));
38	}
39	
40	let idleTimer = null;
41	let warningTimer = null;
42	let _verifiedUser = null; // DB-verified user; set by requireRole, cleared on logout
43	
44	function validatePassword(password) {
45	  return _validatePassword(password);
46	}
47	
48	function isAccountLocked(user) {
49	  return _isAccountLocked(user);
50	}
51	
52	async function register(username, password, role = 'visitor') {
53	  const safeRole = 'visitor';
54	  const validation = validatePassword(password);
55	  if (!validation.valid) return { success: false, errors: validation.errors };
56	
57	  const existing = await DB.getOneByIndex('users', 'username', username);
58	  if (existing) return { success: false, errors: ['Username already exists'] };
59	
60	  const { hash, salt } = await Crypto.hashPassword(password);
61	  const user = {
62	    username,
63	    passwordHash: hash,
64	    passwordSalt: salt,
65	    role: safeRole,
66	    failedAttempts: 0,
67	    lockedUntil: null,
68	    banned: false,
69	    createdAt: Date.now()
70	  };
71	
72	  const id = await DB.add('users', user);
73	  await addAuditLog('user_register', 'system', { userId: id, username, role: safeRole });
74	  return { success: true, userId: id };
75	}
76	
77	// Internal helper — creates a user with the given role. No auth check; callers must gate access.
78	async function _createUserWithRole(username, password, role, auditActor) {
79	  const validation = validatePassword(password);
80	  if (!validation.valid) return { success: false, errors: validation.errors };
81	
82	  const existing = await DB.getOneByIndex('users', 'username', username);
83	  if (existing) return { success: false, errors: ['Username already exists'] };
84	
85	  const { hash, salt } = await Crypto.hashPassword(password);
86	  const user = {
87	    username,
88	    passwordHash: hash,
89	    passwordSalt: salt,
90	    role,
91	    failedAttempts: 0,
92	    lockedUntil: null,
93	    banned: false,
94	    createdAt: Date.now()
95	  };
96	
97	  const id = await DB.add('users', user);
98	
99	  // Wrap the shared DEK for this new user using their password-derived KEK
100	  const kek = await Crypto.deriveKEK(password);
101	  const wrappedKeys = getWrappedKeys();
102	  const currentDEK = getEncryptionKey();
103	  if (currentDEK) {
104	    // Admin is logged in — wrap existing DEK for the new user
105	    const wrappedData = await Crypto.wrapDEK(currentDEK, kek);
106	    wrappedKeys[username] = wrappedData;
107	  } else {
108	    // First-run bootstrap (no DEK yet) — generate a new DEK and wrap it
109	    const dek = await Crypto.generateDEK();
110	    const wrappedData = await Crypto.wrapDEK(dek, kek);
111	    wrappedKeys[username] = wrappedData;
112	  }
113	  setWrappedKeys(wrappedKeys);
114	
115	  await addAuditLog('user_register', auditActor, { userId: id, username, role });
116	  return { success: true, userId: id };
117	}
118	
119	async function registerWithRole(username, password, role, actor) {
120	  // Function-level authorization: actor is required and must be admin — fail closed
121	  if (!actor || actor.role !== 'admin') {
122	    return { success: false, errors: ['Only administrators can create users with specific roles'] };
123	  }
124	  return _createUserWithRole(username, password, role, actor.username);
125	}
126	
127	async function login(username, password) {
128	  const [userRl, globalRl] = await Promise.all([
129	    checkRateLimit('user', username, 'user_login'),
130	    checkRateLimit('global', '', 'user_login')
131	  ]);
132	  if (!userRl.allowed || !globalRl.allowed) {
133	    await addAuditLog('login_rate_limited', username, { remaining: Math.min(userRl.remaining, globalRl.remaining) });
134	    return { success: false, error: 'Too many login attempts. Please try again later.' };
135	  }
136	
137	  const user = await DB.getOneByIndex('users', 'username', username);
138	  if (!user) return { success: false, error: 'Invalid credentials' };
139	  if (user.banned) return { success: false, error: 'Account is banned' };
140	  if (isAccountLocked(user)) {
141	    const remaining = Math.ceil((user.lockedUntil - Date.now()) / 60000);
142	    return { success: false, error: `Account locked. Try again in ${remaining} minute(s).` };
143	  }
144	
145	  // Derive KEK and try to unwrap DEK before password verification so that
146	  // encrypted credential fields (passwordHash, passwordSalt) can be decrypted.
147	  const kek = await Crypto.deriveKEK(password);
148	  const wrappedKeys = getWrappedKeys();
149	  const userWrapped = wrappedKeys[username];
150	  let fullUser = user;
151	
152	  if (userWrapped) {
153	    try {
154	      const dek = await Crypto.unwrapDEK(userWrapped, kek);
155	      setEncryptionKey(dek);
156	      // Re-fetch user with decryption now enabled to access passwordHash/Salt
157	      fullUser = await DB.getOneByIndex('users', 'username', username);
158	    } catch {
159	      // DEK unwrap failed — password is wrong
160	      const result = processFailedLogin(user);
161	      await DB.put('users', user);
162	      if (result.locked) {
163	        await addAuditLog('account_locked', username, { reason: 'max_failed_attempts' });
164	        return { success: false, error: 'Account locked for 15 minutes due to too many failed attempts.' };
165	      }
166	      return { success: false, error: 'Invalid credentials', attemptsLeft: result.attemptsLeft };
167	    }
168	  }
169	
170	  const valid = await Crypto.verifyPassword(password, fullUser.passwordHash, fullUser.passwordSalt);
171	  if (!valid) {
172	    const result = processFailedLogin(user);
173	    clearEncryptionKey();
174	    await DB.put('users', user);
175	    if (result.locked) {
176	      await addAuditLog('account_locked', username, { reason: 'max_failed_attempts' });
177	      return { success: false, error: 'Account locked for 15 minutes due to too many failed attempts.' };
178	    }
179	    return { success: false, error: 'Invalid credentials', attemptsLeft: result.attemptsLeft };
180	  }
181	
182	  processSuccessfulLogin(user);
183	  await DB.put('users', user);
184	
185	  const token = Crypto.generateId();
186	  const session = {
187	    token,
188	    userId: user.id,
189	    username: user.username,
190	    role: user.role,
191	    createdAt: Date.now(),
192	    lastActivity: Date.now()
193	  };
194	
195	  localStorage.setItem(SESSION_KEY, JSON.stringify(session));
196	  Store.set('session', session);
197	  Store.set('currentUser', { id: user.id, username: user.username, role: user.role });
198	
199	  startIdleTimer();
200	  await addAuditLog('user_login', username, { userId: user.id });
201	  return { success: true, session };
202	}
203	
204	function getSession() {
205	  const raw = localStorage.getItem(SESSION_KEY);
206	  if (!raw) return null;
207	  try {
